5	[ "$out" = "purged 2 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
6	[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'z$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
7	ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
8	ARCHIVE=$t bash tools/purge-archive --before 2025-01-08 >/dev/null; grep -q 'z$' "$t" || { echo "a row of the same date should stay"; fail=1; }
9	rm -f "$t"; exit $fail
